//! The simulator data structures shared with the simulator plugins, generated by bindgen from
//! `include/lambiase/{forecast,scoring,telemetry}.h` (see `build.rs`).
#![allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code
)]

include!(concat!(env!("OUT_DIR"), "/sim.rs"));

use std::{
    fmt::{self, Debug, Formatter},
    mem::{ManuallyDrop, MaybeUninit},
    ops::{Deref, DerefMut},
};

// The `lambiase_opt_*` types from lambiase.h, written by hand instead of generated (`build.rs`
// blocklists them) so `value` can be a `MaybeUninit`: it's only initialized when `present` is
// true, and C may leave anything in it otherwise (a garbage `bool`, a null string). Generated
// structs refer to them through the `_s` aliases, so their layout checks cover these types too.
macro_rules! copy_optional {
    ($name:ident, $alias:ident, $t:ty) => {
        #[repr(C)]
        #[derive(Clone, Copy)]
        pub struct $name {
            present: bool,
            value: MaybeUninit<$t>,
        }

        pub type $alias = $name;

        impl $name {
            #[inline]
            pub fn get(&self) -> Option<$t> {
                self.present.then(|| unsafe { self.value.assume_init() })
            }
        }

        impl From<Option<$t>> for $name {
            #[inline]
            fn from(value: Option<$t>) -> Self {
                match value {
                    Some(value) => Self {
                        present: true,
                        value: MaybeUninit::new(value),
                    },
                    None => Self::default(),
                }
            }
        }

        impl From<$name> for Option<$t> {
            #[inline]
            fn from(value: $name) -> Self {
                value.get()
            }
        }

        impl Default for $name {
            #[inline]
            fn default() -> Self {
                Self {
                    present: false,
                    value: MaybeUninit::uninit(),
                }
            }
        }

        impl Debug for $name {
            fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
                Debug::fmt(&self.get(), f)
            }
        }
    };
}

copy_optional!(lambiase_opt_f64, lambiase_opt_f64_s, f64);
copy_optional!(lambiase_opt_i64, lambiase_opt_i64_s, i64);
copy_optional!(lambiase_opt_boolean, lambiase_opt_boolean_s, bool);

#[repr(C)]
pub struct lambiase_opt_string {
    present: bool,
    value: MaybeUninit<lambiase_string_s>,
}

pub type lambiase_opt_string_s = lambiase_opt_string;

impl lambiase_opt_string {
    #[inline]
    pub fn as_deref(&self) -> Option<&str> {
        self.present
            .then(|| unsafe { self.value.assume_init_ref() }.deref())
    }
}

impl<T: Into<lambiase_string>> From<Option<T>> for lambiase_opt_string {
    #[inline]
    fn from(value: Option<T>) -> Self {
        match value {
            Some(value) => Self {
                present: true,
                value: MaybeUninit::new(value.into()),
            },
            None => Self::default(),
        }
    }
}

impl From<lambiase_opt_string> for Option<String> {
    #[inline]
    fn from(value: lambiase_opt_string) -> Self {
        // Moves `value` out without running this type's destructor
        let value = ManuallyDrop::new(value);
        value
            .present
            .then(|| unsafe { value.value.assume_init_read() }.into())
    }
}

impl Default for lambiase_opt_string {
    #[inline]
    fn default() -> Self {
        Self {
            present: false,
            value: MaybeUninit::uninit(),
        }
    }
}

impl Clone for lambiase_opt_string {
    fn clone(&self) -> Self {
        self.as_deref().map(str::to_owned).into()
    }
}

impl Debug for lambiase_opt_string {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        Debug::fmt(&self.as_deref(), f)
    }
}

impl Drop for lambiase_opt_string {
    fn drop(&mut self) {
        if self.present {
            unsafe { self.value.assume_init_drop() };
        }
    }
}

impl Default for lambiase_string {
    #[inline]
    fn default() -> Self {
        String::new().into()
    }
}

impl Deref for lambiase_string {
    type Target = str;

    #[inline(always)]
    fn deref(&self) -> &Self::Target {
        unsafe { std::str::from_utf8_unchecked(std::slice::from_raw_parts(self.data, self.len)) }
    }
}

impl DerefMut for lambiase_string {
    #[inline(always)]
    fn deref_mut(&mut self) -> &mut Self::Target {
        unsafe {
            std::str::from_utf8_unchecked_mut(std::slice::from_raw_parts_mut(self.data, self.len))
        }
    }
}

impl Clone for lambiase_string {
    fn clone(&self) -> Self {
        self.deref().to_owned().into()
    }
}

impl From<String> for lambiase_string {
    #[inline]
    fn from(value: String) -> Self {
        let (data, len, cap) = value.into_raw_parts();
        Self { data, len, cap }
    }
}

impl From<Box<str>> for lambiase_string {
    #[inline]
    fn from(value: Box<str>) -> Self {
        value.into_string().into()
    }
}

impl From<lambiase_string> for String {
    #[inline]
    fn from(value: lambiase_string) -> Self {
        let value = ManuallyDrop::new(value);
        unsafe { String::from_raw_parts(value.data, value.len, value.cap) }
    }
}

impl From<lambiase_string> for Box<str> {
    #[inline]
    fn from(value: lambiase_string) -> Self {
        String::from(value).into_boxed_str()
    }
}

impl Drop for lambiase_string {
    #[inline]
    fn drop(&mut self) {
        drop(unsafe { String::from_raw_parts(self.data, self.len, self.cap) })
    }
}
